// OTLP protobuf decode via the vendored static module (generated by scripts/gen-otlp-proto.sh);
// proto3 skips unknown fields, so newer OTLP revisions degrade gracefully.

import { opentelemetry } from "./otlp/gen/otlp.js";
import type {
  AttrValue,
  Attrs,
  RawLogRecord,
  RawResource,
  RawScope,
  RawSpan,
  RawSpanEvent,
  RawSpanLink,
} from "./raw-span.js";
import { bytesToHex, int64ToBigInt, int64ToJs } from "./raw-span.js";

const TraceRequest = opentelemetry.proto.collector.trace.v1.ExportTraceServiceRequest;
const LogsRequest = opentelemetry.proto.collector.logs.v1.ExportLogsServiceRequest;

type ProtoAnyValue = opentelemetry.proto.common.v1.IAnyValue | null | undefined;

function anyValueToJs(v: ProtoAnyValue): AttrValue {
  if (v === null || v === undefined) return null;
  if (v.stringValue !== null && v.stringValue !== undefined) return v.stringValue;
  if (v.boolValue !== null && v.boolValue !== undefined) return v.boolValue;
  if (v.intValue !== null && v.intValue !== undefined) return int64ToJs(v.intValue);
  if (v.doubleValue !== null && v.doubleValue !== undefined) return v.doubleValue;
  if (v.bytesValue !== null && v.bytesValue !== undefined) {
    return { "@bytes": Buffer.from(v.bytesValue).toString("base64") };
  }
  if (v.arrayValue !== null && v.arrayValue !== undefined) {
    return (v.arrayValue.values ?? []).map(anyValueToJs);
  }
  if (v.kvlistValue !== null && v.kvlistValue !== undefined) {
    const out: { [key: string]: AttrValue } = {};
    for (const kv of v.kvlistValue.values ?? []) {
      if (kv.key !== null && kv.key !== undefined) out[kv.key] = anyValueToJs(kv.value);
    }
    return out;
  }
  return null;
}

function attrsToJs(list: opentelemetry.proto.common.v1.IKeyValue[] | null | undefined): Attrs {
  const out: Attrs = {};
  for (const kv of list ?? []) {
    if (kv.key !== null && kv.key !== undefined) out[kv.key] = anyValueToJs(kv.value);
  }
  return out;
}

function hexId(bytes: Uint8Array | null | undefined): string {
  if (bytes === null || bytes === undefined || bytes.length === 0) return "";
  return bytesToHex(bytes);
}

function nanos(v: number | { toString(): string } | null | undefined): bigint {
  if (v === null || v === undefined) return 0n;
  return int64ToBigInt(v);
}

function decodeResource(r: opentelemetry.proto.resource.v1.IResource | null | undefined): RawResource {
  const resource: RawResource = { attributes: attrsToJs(r?.attributes) };
  if (r?.droppedAttributesCount) resource.droppedAttributesCount = r.droppedAttributesCount;
  return resource;
}

function decodeScope(
  s: opentelemetry.proto.common.v1.IInstrumentationScope | null | undefined,
): RawScope | undefined {
  if (s === null || s === undefined) return undefined;
  const scope: RawScope = {};
  if (s.name !== null && s.name !== undefined && s.name !== "") scope.name = s.name;
  if (s.version !== null && s.version !== undefined && s.version !== "") scope.version = s.version;
  const attrs = attrsToJs(s.attributes);
  if (Object.keys(attrs).length > 0) scope.attributes = attrs;
  return Object.keys(scope).length > 0 ? scope : undefined;
}

export function decodeTracesProtobuf(body: Uint8Array): RawSpan[] {
  const request = TraceRequest.decode(body);
  const spans: RawSpan[] = [];
  for (const rs of request.resourceSpans) {
    const resource = decodeResource(rs.resource);
    for (const ss of rs.scopeSpans ?? []) {
      const scope = decodeScope(ss.scope);
      for (const s of ss.spans ?? []) {
        const span: RawSpan = {
          traceId: hexId(s.traceId),
          spanId: hexId(s.spanId),
          name: s.name ?? "",
          kind: typeof s.kind === "number" ? s.kind : 0,
          startTimeUnixNano: nanos(s.startTimeUnixNano),
          endTimeUnixNano: nanos(s.endTimeUnixNano),
          attributes: attrsToJs(s.attributes),
          events: (s.events ?? []).map((e): RawSpanEvent => {
            const ev: RawSpanEvent = {
              timeUnixNano: nanos(e.timeUnixNano),
              name: e.name ?? "",
              attributes: attrsToJs(e.attributes),
            };
            if (e.droppedAttributesCount) ev.droppedAttributesCount = e.droppedAttributesCount;
            return ev;
          }),
          links: (s.links ?? []).map((l): RawSpanLink => {
            const link: RawSpanLink = {
              traceId: hexId(l.traceId),
              spanId: hexId(l.spanId),
              attributes: attrsToJs(l.attributes),
            };
            if (l.traceState !== null && l.traceState !== undefined && l.traceState !== "") {
              link.traceState = l.traceState;
            }
            return link;
          }),
          resource,
        };
        const parent = hexId(s.parentSpanId);
        if (parent !== "") span.parentSpanId = parent;
        if (scope !== undefined) span.scope = scope;
        if (s.traceState !== null && s.traceState !== undefined && s.traceState !== "") {
          span.traceState = s.traceState;
        }
        if (s.status !== null && s.status !== undefined) {
          const code = typeof s.status.code === "number" ? s.status.code : 0;
          const message = s.status.message ?? "";
          if (code !== 0 || message !== "") {
            span.status = { code };
            if (message !== "") span.status.message = message;
          }
        }
        if (s.droppedAttributesCount) span.droppedAttributesCount = s.droppedAttributesCount;
        if (s.droppedEventsCount) span.droppedEventsCount = s.droppedEventsCount;
        if (s.droppedLinksCount) span.droppedLinksCount = s.droppedLinksCount;
        spans.push(span);
      }
    }
  }
  return spans;
}

export function decodeLogsProtobuf(body: Uint8Array): RawLogRecord[] {
  const request = LogsRequest.decode(body);
  const records: RawLogRecord[] = [];
  for (const rl of request.resourceLogs) {
    const resource = decodeResource(rl.resource);
    for (const sl of rl.scopeLogs ?? []) {
      const scope = decodeScope(sl.scope);
      for (const r of sl.logRecords ?? []) {
        const record: RawLogRecord = { attributes: attrsToJs(r.attributes), resource };
        const t = nanos(r.timeUnixNano);
        if (t > 0n) record.timeUnixNano = t;
        const ot = nanos(r.observedTimeUnixNano);
        if (ot > 0n) record.observedTimeUnixNano = ot;
        if (r.severityText !== null && r.severityText !== undefined && r.severityText !== "") {
          record.severityText = r.severityText;
        }
        if (typeof r.severityNumber === "number" && r.severityNumber !== 0) {
          record.severityNumber = r.severityNumber;
        }
        if (r.eventName !== null && r.eventName !== undefined && r.eventName !== "") {
          record.eventName = r.eventName;
        }
        if (r.body !== null && r.body !== undefined) record.body = anyValueToJs(r.body);
        const traceId = hexId(r.traceId);
        if (traceId !== "") record.traceId = traceId;
        const spanId = hexId(r.spanId);
        if (spanId !== "") record.spanId = spanId;
        if (scope !== undefined) record.scope = scope;
        records.push(record);
      }
    }
  }
  return records;
}
